import boto3,json,os,time,uuid,base64
s3=boto3.client('s3')
def invoke(event,context):
    body=event.get('body') or ''
    if event.get('isBase64Encoded'): body=base64.b64decode(body).decode('utf-8')
    try: message=json.loads(body)
    except (ValueError,TypeError): message={}
    path=event['rawPath'].strip('/')
    status=503 if path=='confirm503' else (200 if path=='raw' else int(path))
    if message.get('Type') in ('SubscriptionConfirmation','UnsubscribeConfirmation') and path!='confirm503': status=200
    if path=='confirm503' and message.get('Type')=='Notification': status=200
    response={'statusCode':status,'headers':{'Content-Type':'text/plain','X-Probe-Response':str(status)},'body':'observed status '+str(status)}
    if status==302: response['headers']['Location']='/200'
    record={'received_at':time.time(),'path':path,'body':body,'message':message,'event':event,'response':response}
    s3.put_object(Bucket=os.environ['BUCKET'],Key='receipts/'+str(time.time_ns())+'-'+str(uuid.uuid4())+'.json',Body=json.dumps(record).encode())
    return response
